result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "scaffold-node.mjs", "content": "#!/usr/bin/env node
// scaffold-node.mjs — generate a working npm package with zero dependencies.
// Usage: node scaffold-node.mjs <package-name>

import { existsSync, mkdirSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";

const name = process.argv[2];

if (!name) {
  console.error("Usage: node scaffold-node.mjs <package-name>");
  process.exit(1);
}

if (!/^[a-z0-9][a-z0-9._-]*$/i.test(name)) {
  console.error(`error: invalid package name "${name}"`);
  process.exit(1);
}

const root = resolve(name);
if (existsSync(root)) {
  console.error(`error: target directory already exists: ${root}`);
  process.exit(1);
}

const srcDir = join(root, "src");
const testDir = join(root, "test");

mkdirSync(srcDir, { recursive: true });
mkdirSync(testDir, { recursive: true });

const pkgName = name.toLowerCase().replace(/[^a-z0-9._-]/g, "-");

writeFileSync(
  join(root, "package.json"),
  JSON.stringify(
    {
      name: pkgName,
      version: "0.1.0",
      description: `${pkgName} — a tiny utility package`,
      type: "module",
      main: "src/index.mjs",
      exports: "./src/index.mjs",
      scripts: {
        test: "node --test"
      },
      license: "MIT"
    },
    null,
    2
  ) + "\n"
);

writeFileSync(join(root, ".gitignore"), "node_modules/\n");

writeFileSync(
  join(root, "README.md"),
  `# ${pkgName}\n\nA tiny utility package.\n\n## Install\n\n\`\`\`sh\nnpm install ${pkgName}\n\`\`\`\n\n## API\n\n### slugify(str)\n\nLowercases \`str\`, converts runs of non-alphanumeric characters to single\nhyphens, and trims hyphens from the ends.\n\n\`\`\`mjs\nimport { slugify } from "${pkgName}";\nslugify(" Hello, World! "); // "hello-world"\n\`\`\`\n`
);

writeFileSync(
  join(root, "src", "index.mjs"),
  `/**\n * Convert a string into a URL-friendly slug.\n *\n * - Lowercases the input (Unicode-aware).\n * - Replaces every run of characters that are not Unicode letters or digits\n *   with a single hyphen.\n * - Trims leading/trailing hyphens.\n *\n * @param {string} str\n * @returns {string}\n */\nexport function slugify(str) {\n  if (typeof str !== "string") {\n    throw new TypeError("slugify expects a string");\n  }\n  return (\n    str\n      .toLowerCase()\n      .replace(/[^\\p{L}\\p{N}]+/gu, "-")\n      .replace(/^-+|-+$/g, "")\n  );\n}\n`
);

writeFileSync(
  join(root, "test", "index.test.mjs"),
  `import test from "node:test";\nimport assert from "node:assert/strict";\n\nimport { slugify } from "../src/index.mjs";\n\ntest("' Hello, World! ' -> 'hello-world'", () => {\n  assert.equal(slugify(" Hello, World! "), "hello-world");\n});\n\ntest("unicode letters are kept", () => {\n  // German umlauts, Greek letters, CJK, accented Latin — all preserved.\n  assert.equal(slugify("Über Straße"), "über-straße");\n  assert.equal(slugify("Ελληνικά 中文"), "ελληνικά-中文");\n});\n\ntest("empty string -> empty string", () => {\n  assert.equal(slugify(""), "");\n});\n\ntest("runs of separators collapse to a single hyphen", () => {\n  assert.equal(slugify("a   b///c---d"), "a-b-c-d");\n});\n`
);

console.log(`Scaffolded package "${pkgName}" in ${root}/`);
console.log(`  package.json`);
console.log(`  src/index.mjs`);
console.log(`  test/index.test.mjs`);
console.log("");
console.log(`Next steps:`);
console.log(`  cd ${name}`);
console.log(`  npm test`);
"})
